type PaymentFailed = { type: 'payment-failed'; orderId: number; reason: string };
type OrderShipped = { type: 'order-shipped'; orderId: number; carrier: string };
type CheckoutEvent = PaymentFailed | OrderShipped;

// Cartwheel's checkout event bus.
// Property syntax: the parameter is checked strictly (contravariantly).
interface CheckoutListener {
  onEvent: (event: CheckoutEvent) => void;
}

const listeners: CheckoutListener[] = [];
const seen: string[] = [];

function subscribe(listener: CheckoutListener): void {
  listeners.push(listener);
}

function emit(event: CheckoutEvent): void {
  for (const l of listeners) l.onEvent(event);
}

// Handles every event: must keep compiling.
subscribe({ onEvent: (e) => { seen.push(`${e.type}:${e.orderId}`); } });

// A listener that takes no arguments at all: must keep compiling too.
subscribe({ onEvent: () => { seen.push('ping'); } });

// ---- Type tests (do not edit) ----
// This listener only understands PaymentFailed; an OrderShipped event would
// crash it (e.reason is undefined). Subscribing it must be a type error.
const failuresOnly = { onEvent: (e: PaymentFailed) => { seen.push(e.reason.toUpperCase()); } };
